static constexpr int NV=6; static constexpr int N=64; static constexpr mpfr_prec_t PREC=256; static const int BINOM[7]={1,6,15,20,15,6,1};
static mpq_class Q(long n,long d=1){ mpq_class q(n,d); q.canonicalize(); return q; }
