struct Poset{std::array<uint64_t,N>pred{},succ{};Poset(){for(int i=0;i<NV;i++)for(int j=i+1;j<NV;j++)for(uint64_t base=0;base<(1ull<<NV);base++){if(base&((1ull<<i)|(1ull<<j)))continue;uint64_t v00=base,v01=base|(1ull<<j),v10=base|(1ull<<i),v11=base|(1ull<<i)|(1ull<<j);pred[v01]|=(1ull<<v00);pred[v10]|=(1ull<<v01);pred[v11]|=(1ull<<v10);}for(int pass=0;pass<N;pass++){bool changed=false;for(int v=0;v<N;v++){uint64_t q=pred[v],y=q;while(y){uint64_t bit=y&(~y+1ull);int b=__builtin_ctzll(y);q|=pred[b];y-=bit;}if(q!=pred[v]){pred[v]=q;changed=true;}}if(!changed)break;}for(int u=0;u<N;u++){uint64_t y=pred[u];while(y){uint64_t bit=y&(~y+1ull);int v=__builtin_ctzll(y);succ[v]|=(1ull<<u);y-=bit;}}}int minimal(uint64_t avail)const{uint64_t y=avail;while(y){int v=__builtin_ctzll(y);uint64_t bit=1ull<<v;if((pred[v]&avail)==0)return v;y-=bit;}return -1;}void rec(uint64_t avail,uint64_t included,std::vector<uint64_t>&out)const{if(!avail){out.push_back(included);return;}int m=minimal(avail);assert(m>=0);uint64_t bit=1ull<<m;rec(avail&~bit,included|bit,out);rec(avail&~bit&~succ[m],included,out);}std::vector<uint64_t>ideals()const{std::vector<uint64_t>out;rec(0xffffffffffffffffull,0u,out);std::sort(out.begin(),out.end());out.erase(std::unique(out.begin(),out.end()),out.end());return out;}};
static bool pair_compressed(uint64_t mask){for(int i=0;i<NV;i++)for(int j=i+1;j<NV;j++)for(uint64_t base=0;base<(1ull<<NV);base++){if(base&((1ull<<i)|(1ull<<j)))continue;uint32_t v[4]={static_cast<uint32_t>(base),static_cast<uint32_t>(base|(1ull<<j)),static_cast<uint32_t>(base|(1ull<<i)),static_cast<uint32_t>(base|(1ull<<i)|(1ull<<j))};bool seen0=false;for(int k=0;k<4;k++){bool in=(mask>>v[k])&1u;if(!in)seen0=true;else if(seen0)return false;}}return true;}
static bool is_constant(uint64_t m){return m==0u||m==0xffffffffffffffffull;} static bool is_dictator(uint64_t m){for(int i=0;i<NV;i++){uint64_t d=0;for(uint32_t x=0;x<(1ull<<NV);x++)if((x>>i)&1u)d|=(1ull<<x);if(m==d||m==(0xffffffffffffffffull^d))return true;}return false;}
using Poly=std::array<mpq_class,7>; static Poly qpoly(uint64_t mask,int y){int c[7]={0,0,0,0,0,0,0};for(int x=0;x<N;x++)if((mask>>x)&1u)c[__builtin_popcountll((unsigned long long)(x^y))]++;Poly p;for(int d=0;d<=NV;d++)p[d]=Q(c[d],BINOM[d]);return p;}
static std::pair<Poly,Poly>subdivide(const Poly&c,const mpq_class&t){mpq_class row[7][7];for(int i=0;i<7;i++)row[0][i]=c[i];for(int r=1;r<7;r++)for(int i=0;i<7-r;i++)row[r][i]=(1-t)*row[r-1][i]+t*row[r-1][i+1];Poly L,R;for(int i=0;i<7;i++){L[i]=row[i][0];R[i]=row[6-i][i];}return{L,R};}
static Poly restrict_poly(const Poly&c,const mpq_class&a,const mpq_class&b){Poly left=c;if(b!=1)left=subdivide(c,b).first;if(a==0)return left;return subdivide(left,a/b).second;} static mpq_class eval_poly(const Poly&c,const mpq_class&a){std::vector<mpq_class>cur(c.begin(),c.end());while(cur.size()>1){std::vector<mpq_class>nxt;for(size_t i=0;i+1<cur.size();i++)nxt.push_back((1-a)*cur[i]+a*cur[i+1]);cur.swap(nxt);}return cur[0];}
static std::string pkey(const Poly&p){std::ostringstream os;for(auto&q:p)os<<q.get_num()<<'/'<<q.get_den()<<';';return os.str();} struct Group{Poly p;int mult;}; static std::vector<Group>make_groups(uint64_t mask){std::map<std::string,std::pair<Poly,int>>tmp;for(int y=0;y<N;y++){Poly q=qpoly(mask,y);std::string k=pkey(q);auto it=tmp.find(k);if(it==tmp.end())tmp[k]={q,1};else it->second.second++;}std::vector<Group>out;for(auto&kv:tmp)out.push_back({kv.second.first,kv.second.second});return out;}
static void entropy_min_endpoint(const mpq_class&loq,const mpq_class&hiq,MP&hlo,MP&hhi){mpq_class dlo=abs(2*loq-1),dhi=abs(2*hiq-1);entropy_bounds(dlo>=dhi?loq:hiq,hlo,hhi);} static void D_point(uint64_t mask,const mpq_class&a,const std::vector<Group>&groups,MP&dlo,MP&dhi,const MP&ln2lo,const MP&ln2hi){mpq_class p=Q(__builtin_popcountll(mask),N);MP haL,haU,hpL,hpU,sumL,sumU;entropy_bounds(a,haL,haU);entropy_bounds(p,hpL,hpU);mpfr_set(dlo.v,ln2lo.v,MPFR_RNDD);mpfr_set(dhi.v,ln2hi.v,MPFR_RNDU);mpfr_sub(dlo.v,dlo.v,haU.v,MPFR_RNDD);mpfr_sub(dhi.v,dhi.v,haL.v,MPFR_RNDU);mpfr_sub(dlo.v,dlo.v,hpU.v,MPFR_RNDD);mpfr_sub(dhi.v,dhi.v,hpL.v,MPFR_RNDU);mpfr_set_ui(sumL.v,0,MPFR_RNDN);mpfr_set_ui(sumU.v,0,MPFR_RNDN);for(const auto&g:groups){mpq_class q=eval_poly(g.p,a);MP qL,qU;entropy_bounds(q,qL,qU);for(int k=0;k<g.mult;k++){mpfr_add(sumL.v,sumL.v,qL.v,MPFR_RNDD);mpfr_add(sumU.v,sumU.v,qU.v,MPFR_RNDU);}}mpfr_div_ui(sumL.v,sumL.v,N,MPFR_RNDD);mpfr_div_ui(sumU.v,sumU.v,N,MPFR_RNDU);mpfr_add(dlo.v,dlo.v,sumL.v,MPFR_RNDD);mpfr_add(dhi.v,dhi.v,sumU.v,MPFR_RNDU);}
static void D_interval_lower(uint64_t mask,const mpq_class&a,const mpq_class&b,const std::vector<Group>&groups,MP&dlo,const MP&ln2lo){mpq_class p=Q(__builtin_popcountll(mask),N);MP hbL,hbU,hpL,hpU,sumL;entropy_bounds(b,hbL,hbU);entropy_bounds(p,hpL,hpU);mpfr_set(dlo.v,ln2lo.v,MPFR_RNDD);mpfr_sub(dlo.v,dlo.v,hbU.v,MPFR_RNDD);mpfr_sub(dlo.v,dlo.v,hpU.v,MPFR_RNDD);mpfr_set_ui(sumL.v,0,MPFR_RNDN);for(const auto&g:groups){Poly r=restrict_poly(g.p,a,b);mpq_class lo=r[0],hi=r[0];for(int i=1;i<7;i++){if(r[i]<lo)lo=r[i];if(r[i]>hi)hi=r[i];}MP hL,hU;entropy_min_endpoint(lo,hi,hL,hU);for(int k=0;k<g.mult;k++)mpfr_add(sumL.v,sumL.v,hL.v,MPFR_RNDD);}mpfr_div_ui(sumL.v,sumL.v,N,MPFR_RNDD);mpfr_add(dlo.v,dlo.v,sumL.v,MPFR_RNDD);}
static std::array<mpq_class,N>walsh_pm(uint64_t mask){std::array<mpq_class,N>c;for(int S=0;S<N;S++){int s=0;for(int x=0;x<N;x++){int v=((mask>>x)&1u)?-1:1;int chi=(__builtin_popcountll((unsigned long long)(x&S))&1)?-1:1;s+=v*chi;}c[S]=Q(s,N);}return c;} static mpq_class avg_sensitivity(uint64_t mask){long ss=0;for(int x=0;x<N;x++)for(int i=0;i<NV;i++)ss+=(((mask>>x)&1u)!=((mask>>(x^(1<<i)))&1u));return Q(ss,N);}
struct IntervalStats{long long nodes=0,leaves=0;int maxdepth=0;double min_lb=1e300;uint32_t worstmask=0;}; static bool certify_middle(uint64_t mask,const std::vector<Group>&groups,const mpq_class&A0,const mpq_class&A1,const MP&ln2lo,IntervalStats&st,int maxdepth=30){struct Node{mpq_class a,b;int d;};std::vector<Node>stack;stack.push_back({A0,A1,0});while(!stack.empty()){Node z=stack.back();stack.pop_back();st.nodes++;st.maxdepth=std::max(st.maxdepth,z.d);MP lb;D_interval_lower(mask,z.a,z.b,groups,lb,ln2lo);if(mpfr_cmp_si(lb.v,0)>0){st.leaves++;double v=getd(lb);if(v<st.min_lb){st.min_lb=v;st.worstmask=(uint32_t)mask;}continue;}if(z.d>=maxdepth){std::cerr<<"UNCERTIFIED mask="<<mask<<" depth="<<z.d<<" a="<<z.a<<" b="<<z.b<<" lb="<<std::setprecision(17)<<getd(lb)<<"\n";return false;}mpq_class mid=(z.a+z.b)/2;stack.push_back({mid,z.b,z.d+1});stack.push_back({z.a,mid,z.d+1});}return true;}
